INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (100, 1, NULL, 'Mix dry ingredients', 'In a large bowl, whisk together the flour, sugar, baking powder, and a pinch of salt until well combined.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (100, 2, NULL, 'Combine wet ingredients', 'In a separate bowl, whisk together the milk, melted butter, eggs, and vanilla extract.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (100, 3, NULL, 'Make the batter', 'Pour the wet ingredients into the dry ingredients and stir gently until just combined. A few small lumps are fine — do not overmix.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (100, 4, NULL, 'Cook the pancakes', 'Heat a non-stick skillet or griddle over medium heat and lightly grease with butter. Pour about 1/4 cup of batter per pancake. Cook until bubbles form on the surface, about 2-3 minutes, then flip and cook another 1-2 minutes until golden.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (100, 5, NULL, 'Serve', 'Stack pancakes on plates and serve warm with maple syrup, fresh butter, and blueberries if desired.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (101, 1, NULL, 'Prep vegetables', 'Dice the bell pepper and onion into small pieces. Roughly chop the spinach.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (101, 2, NULL, 'Saute vegetables', 'Heat olive oil in a non-stick skillet over medium heat. Add the bell pepper and onion, cooking for 3-4 minutes until softened. Add the spinach and cook until wilted, about 1 minute.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (101, 3, NULL, 'Scramble the eggs', 'Crack the eggs into a bowl, season with salt and pepper, and whisk until frothy. Pour over the vegetables and gently stir with a spatula, folding the curds as they form.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (101, 4, NULL, 'Serve', 'Remove from heat while eggs are still slightly wet — they will continue cooking. Serve immediately on warm plates.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (102, 1, NULL, 'Blend the base', 'Add frozen banana slices, Greek yogurt, and a splash of milk to a blender. Blend until thick and creamy, scraping down sides as needed.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (102, 2, NULL, 'Pour and top', 'Pour the thick smoothie into a bowl. Arrange granola, blueberries, and chia seeds on top in neat rows.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (102, 3, NULL, 'Finish', 'Drizzle with honey and serve immediately while cold and thick.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (103, 1, NULL, 'Make the custard', 'In a shallow bowl, whisk together the eggs, milk, vanilla extract, cinnamon, and a pinch of sugar until smooth.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (103, 2, NULL, 'Soak the bread', 'Dip each slice of bread into the custard, letting it soak for about 15 seconds per side. Allow excess to drip off.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (103, 3, NULL, 'Cook', 'Melt butter in a skillet over medium heat. Cook each soaked slice for 2-3 minutes per side until golden brown and cooked through.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (103, 4, NULL, 'Serve', 'Serve warm, dusted with cinnamon and drizzled with maple syrup.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (104, 1, NULL, 'Wilt the spinach', 'Heat a small amount of olive oil in a non-stick skillet. Add minced garlic and cook for 30 seconds, then add spinach and cook until just wilted. Remove and set aside.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (104, 2, NULL, 'Cook the omelette base', 'Whisk the eggs with salt and pepper. In the same skillet, melt butter over medium-low heat and pour in the eggs. Let them set around the edges, then gently lift to let uncooked egg flow underneath.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (104, 3, NULL, 'Fill and fold', 'When the top is still slightly wet, add the wilted spinach and crumbled feta to one half. Fold the other half over and cook for another 30 seconds.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (104, 4, NULL, 'Serve', 'Slide onto a plate and serve immediately.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (105, 1, NULL, 'Toast the bread', 'Slice the sourdough bread and toast until golden and crisp.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (105, 2, NULL, 'Spread cream cheese', 'Generously spread cream cheese on each toasted slice.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (105, 3, NULL, 'Layer toppings', 'Arrange smoked salmon slices over the cream cheese. Top with thinly sliced red onion, capers, and fresh dill.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (105, 4, NULL, 'Serve', 'Squeeze a bit of lemon juice over the top and serve immediately.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (106, 1, NULL, 'Season and grill chicken', 'Season chicken breasts with salt, pepper, and a drizzle of olive oil. Grill over medium-high heat for 5-6 minutes per side until cooked through (internal temp 165°F). Let rest 5 minutes, then slice into strips.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (106, 2, NULL, 'Prep the lettuce', 'Wash and chop the romaine lettuce into bite-size pieces. Shave or grate the parmesan cheese.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (106, 3, NULL, 'Assemble wraps', 'Warm the tortillas briefly. Layer romaine, chicken strips, and parmesan on each tortilla. Drizzle generously with Caesar dressing.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (106, 4, NULL, 'Roll and serve', 'Tuck in the sides and roll each tortilla tightly. Cut in half diagonally and serve.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (107, 1, NULL, 'Prep ingredients', 'Drain and rinse the black beans and corn. Halve the cherry tomatoes. Finely dice the red onion. Chop the cilantro.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (107, 2, NULL, 'Make the dressing', 'In a small bowl, whisk together the lime juice, olive oil, salt, and pepper.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (107, 3, NULL, 'Combine', 'In a large bowl, combine the black beans, corn, cherry tomatoes, red onion, and cilantro. Pour the dressing over and toss to coat evenly.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (107, 4, NULL, 'Serve', 'Serve immediately or refrigerate for 30 minutes to let the flavors meld. Great on its own or with tortilla chips.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (108, 1, NULL, 'Toast the bread', 'Toast the sourdough bread slices until golden brown.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (108, 2, NULL, 'Prep the avocado', 'Halve the avocado, remove the pit, and slice thinly. Season with a pinch of salt.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (108, 3, NULL, 'Assemble', 'Layer turkey, avocado slices, lettuce, and tomato on two slices of toast. Season with salt and pepper, then top with the remaining bread slices.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (108, 4, NULL, 'Serve', 'Cut diagonally and serve with your favorite side.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (109, 1, NULL, 'Saute aromatics', 'Heat olive oil in a large pot over medium heat. Add diced onion and minced garlic, cooking until softened, about 4-5 minutes.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (109, 2, NULL, 'Add tomatoes and broth', 'Add the chopped tomatoes and vegetable broth. Bring to a boil, then reduce heat and simmer for 20 minutes.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (109, 3, NULL, 'Blend', 'Remove from heat. Add fresh basil leaves and blend with an immersion blender until completely smooth.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (109, 4, NULL, 'Finish and serve', 'Stir in the heavy cream, season with salt and pepper, and heat through for 2 minutes. Serve with crusty bread.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (110, 1, NULL, 'Cook quinoa', 'Rinse the quinoa under cold water. Combine with 2 cups of water in a saucepan, bring to a boil, reduce heat to low, cover, and simmer for 15 minutes until fluffy. Let stand 5 minutes.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (110, 2, NULL, 'Prep vegetables', 'Dice the cucumber, halve the cherry tomatoes, and slice the olives. Dice the red onion finely.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (110, 3, NULL, 'Make vinaigrette', 'Whisk together olive oil, lemon juice, salt, and pepper in a small bowl.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (110, 4, NULL, 'Assemble bowls', 'Divide the quinoa between two bowls. Top with cucumber, cherry tomatoes, olives, red onion, and crumbled feta. Drizzle with vinaigrette.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (111, 1, NULL, 'Make teriyaki sauce', 'Whisk together soy sauce, honey, minced ginger, minced garlic, and sesame oil in a small bowl. Set aside.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (111, 2, NULL, 'Cook chicken', 'Cut chicken into bite-size pieces. Heat olive oil in a wok or large skillet over high heat. Add chicken and cook until golden and cooked through, about 5-6 minutes. Remove and set aside.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (111, 3, NULL, 'Stir-fry broccoli', 'In the same pan, add the broccoli florets and stir-fry for 3-4 minutes until bright green and tender-crisp.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (111, 4, NULL, 'Combine and serve', 'Return the chicken to the pan, pour in the teriyaki sauce, and toss everything together for 1 minute until glazed. Serve over steamed white rice.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (112, 1, NULL, 'Brown the beef', 'Heat olive oil in a large pot over medium-high heat. Add the ground beef and cook, breaking it apart, until well browned, about 6-7 minutes. Drain excess fat.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (112, 2, NULL, 'Saute aromatics', 'Add diced onion and minced garlic to the pot. Cook for 3-4 minutes until softened and fragrant.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (112, 3, NULL, 'Simmer the sauce', 'Pour in the marinara sauce, add dried basil, salt, and pepper. Stir well, bring to a simmer, and cook on low for 20-25 minutes, stirring occasionally.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (112, 4, NULL, 'Cook pasta', 'Meanwhile, cook the spaghetti in a large pot of salted boiling water according to package directions until al dente. Drain, reserving 1/2 cup pasta water.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (112, 5, NULL, 'Serve', 'Toss the spaghetti with the Bolognese sauce, adding a splash of pasta water if needed. Serve topped with freshly grated parmesan.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (113, 1, NULL, 'Make marinade', 'Whisk together olive oil, lemon juice, lemon zest, minced garlic, chopped thyme, salt, and pepper in a bowl.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (113, 2, NULL, 'Marinate chicken', 'Place chicken breasts in the marinade, turning to coat. Let marinate for at least 15 minutes (or up to 4 hours in the refrigerator).', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (113, 3, NULL, 'Grill', 'Preheat grill to medium-high. Grill the chicken for 6-7 minutes per side, until the internal temperature reaches 165°F and grill marks are visible.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (113, 4, NULL, 'Rest and serve', 'Let the chicken rest for 5 minutes before slicing. Serve with a fresh squeeze of lemon and your choice of vegetables.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (114, 1, NULL, 'Saute aromatics', 'Heat olive oil in a large skillet over medium heat. Add minced garlic, grated ginger, and diced onion. Cook for 3-4 minutes until fragrant.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (114, 2, NULL, 'Build the sauce', 'Add curry powder and stir for 30 seconds. Pour in the coconut milk and diced tomatoes, then bring to a gentle simmer.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (114, 3, NULL, 'Cook the shrimp', 'Add the shrimp to the sauce and cook for 4-5 minutes until pink and curled. Season with salt and pepper.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (114, 4, NULL, 'Serve', 'Serve the curry over steamed jasmine rice. Garnish with fresh cilantro.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (115, 1, NULL, 'Preheat oven', 'Preheat your oven to 400°F (200°C). Line a baking sheet with parchment paper.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (115, 2, NULL, 'Prepare salmon', 'Place salmon fillets on the prepared baking sheet. Drizzle with olive oil, squeeze lemon juice over the top, and season with minced garlic, thyme, salt, and pepper.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (115, 3, NULL, 'Prepare asparagus', 'Trim the woody ends of the asparagus. Toss with olive oil, salt, and pepper, and arrange around the salmon on the baking sheet.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (115, 4, NULL, 'Bake and serve', 'Bake for 15-18 minutes until the salmon flakes easily with a fork and the asparagus is tender. Serve with lemon wedges.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (116, 1, NULL, 'Cook the beef', 'Heat olive oil in a skillet over medium-high heat. Add the ground beef and cook, breaking it apart, until browned. Season with cumin, paprika, salt, and pepper.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (116, 2, NULL, 'Make fresh salsa', 'Dice the tomatoes, red onion, and cilantro. Toss together with a squeeze of lime juice and a pinch of salt.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (116, 3, NULL, 'Warm tortillas', 'Heat corn tortillas in a dry skillet or directly over a gas flame for about 30 seconds per side until pliable.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (116, 4, NULL, 'Assemble and serve', 'Fill each tortilla with seasoned beef, top with fresh salsa and diced avocado. Serve with lime wedges and sour cream on the side.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (117, 1, NULL, 'Prepare broth', 'Warm the vegetable broth in a saucepan and keep it at a gentle simmer.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (117, 2, NULL, 'Saute mushrooms', 'In a large heavy-bottomed pot, heat olive oil and butter over medium heat. Add sliced mushrooms and cook until golden, about 5 minutes. Remove and set aside.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (117, 3, NULL, 'Toast rice and deglaze', 'In the same pot, add the diced onion and garlic, cooking until soft. Add the arborio rice and stir for 1-2 minutes until the grains are translucent at the edges. Pour in the white wine and stir until absorbed.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (117, 4, NULL, 'Add broth gradually', 'Add the warm broth one ladle at a time, stirring frequently and waiting until each addition is mostly absorbed before adding the next. This takes about 18-20 minutes.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (117, 5, NULL, 'Finish and serve', 'Stir in the cooked mushrooms, parmesan, and remaining butter. Season with salt, pepper, and thyme. The risotto should be creamy and flow slowly when spooned.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (118, 1, NULL, 'Prep vegetables', 'Wash and peel the carrots. Cut the carrots, celery, and cucumber into sticks about 3 inches long.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (118, 2, NULL, 'Plate and serve', 'Spoon hummus into a small bowl. Drizzle with olive oil and arrange the veggie sticks around it for dipping.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (119, 1, NULL, 'Slice apples', 'Core the apples and cut into thick rounds or wedges.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (119, 2, NULL, 'Top and serve', 'Spread peanut butter on each apple slice. Top with a sprinkle of granola and a drizzle of honey.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (120, 1, NULL, 'Cube the cheese', 'Cut the cheddar cheese into bite-size cubes.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (120, 2, NULL, 'Arrange', 'Arrange the cheese cubes, crackers, and sliced apple on a plate or board.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (121, 1, NULL, 'Combine ingredients', 'In a large bowl, mix together the rolled oats, peanut butter, honey, dark chocolate chips, and chopped almonds until a sticky dough forms.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (121, 2, NULL, 'Chill briefly', 'Refrigerate the mixture for 15 minutes to make it easier to handle.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (121, 3, NULL, 'Roll into balls', 'Scoop about 1 tablespoon of mixture and roll into balls between your palms. Place on a parchment-lined tray.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (121, 4, NULL, 'Store', 'Refrigerate the energy balls in an airtight container. They keep for up to a week.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (122, 1, NULL, 'Prep ingredients', 'Halve the cherry tomatoes if desired. Cut the fresh mozzarella into bite-size cubes. Pick fresh basil leaves.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (122, 2, NULL, 'Assemble skewers', 'Thread a cherry tomato, a basil leaf, and a mozzarella cube onto each skewer. Repeat until all ingredients are used.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (122, 3, NULL, 'Finish', 'Arrange on a plate, drizzle with balsamic glaze and a light drizzle of olive oil. Season with salt and pepper.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (123, 1, NULL, 'Mash avocados', 'Halve the avocados, remove pits, and scoop the flesh into a bowl. Mash with a fork to your preferred consistency — chunky or smooth.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (123, 2, NULL, 'Add seasonings', 'Stir in diced red onion, chopped cilantro, diced tomato, lime juice, salt, and pepper. Mix gently to combine.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (123, 3, NULL, 'Serve', 'Serve immediately with tortilla chips on the side. Press plastic wrap directly on the surface to prevent browning if storing.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (200, 1, NULL, 'Prepare topping', 'Dice the tomatoes and finely chop the fresh basil. Mince the garlic cloves.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (200, 2, NULL, 'Mix topping', 'In a bowl, combine the diced tomatoes, basil, minced garlic, olive oil, salt, and black pepper. Toss gently and let sit for 5 minutes.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
