INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (242, 1, NULL, 'Season the fish', 'Pat salmon fillets dry and season with cumin, paprika, salt, and pepper.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
