INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (249, 1, NULL, 'Saute mushrooms', 'Heat olive oil in a large pan. Saute sliced mushrooms for 5 minutes until golden. Remove and set aside.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (249, 2, NULL, 'Toast the rice', 'In the same pan, saute diced onion until soft. Add arborio rice and stir for 2 minutes until translucent. Add white wine and stir until absorbed.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (249, 3, NULL, 'Add broth gradually', 'Add warm vegetable broth one ladle at a time, stirring constantly. Wait for each addition to be absorbed before adding more. Continue for 18-20 minutes.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
