INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (280, 3, NULL, 'Assemble the salad', 'Chop the romaine lettuce into bite-size pieces and place in a large bowl. Drizzle with dressing, toss to coat, then top with toasted bread cubes and shaved parmesan.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
