INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (296, 2, NULL, 'Finish and serve', 'Drizzle honey over the top and serve immediately for maximum crunch.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (297, 1, NULL, 'Slice cheese', 'Cut the cheddar cheese into thin slices or small cubes that fit neatly on the crackers.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (297, 2, NULL, 'Arrange and serve', 'Arrange crackers on a plate, top each with a slice of cheese and a small dab of Dijon mustard. Serve immediately.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (312, 3, NULL, 'Chill', 'Cover with plastic wrap and refrigerate for at least 4 hours or overnight until firmly set.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (298, 1, NULL, 'Process the base', 'Add pitted Medjool dates to a food processor and pulse until they form a sticky paste. Add almonds and pulse until roughly chopped and combined.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (298, 2, NULL, 'Mix and shape', 'Transfer to a bowl and mix in rolled oats, dark chocolate chips, and a pinch of salt. Press the mixture firmly into a parchment-lined 8x8 baking dish.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (298, 3, NULL, 'Chill and cut', 'Refrigerate for at least 1 hour until firm. Cut into 8 bars and store in the refrigerator.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (299, 1, NULL, 'Blend', 'Add blueberries, banana, Greek yogurt, and milk to a blender. Blend on high until completely smooth and creamy, about 1 minute.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (299, 2, NULL, 'Serve', 'Pour into a tall glass and serve immediately while cold.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (300, 1, NULL, 'Make the batter', 'Preheat oven to 350°F. Mash the bananas in a bowl. Stir in rolled oats, egg, honey, vanilla extract, and cinnamon until well combined.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (300, 2, NULL, 'Bake', 'Spoon the batter into a greased mini muffin tin, filling each cup about 3/4 full. Bake for 12-15 minutes until golden and a toothpick comes out clean.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (300, 3, NULL, 'Cool and serve', 'Let cool in the tin for 5 minutes, then transfer to a wire rack. Serve warm or at room temperature.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (301, 1, NULL, 'Mix ingredients', 'In a large bowl, combine peanut butter, rolled oats, honey, and dark chocolate chips. Stir until a thick, sticky dough forms.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (301, 2, NULL, 'Shape and chill', 'Roll tablespoon-sized portions into balls with your hands. Place on a parchment-lined tray and refrigerate for at least 30 minutes until firm.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (302, 1, NULL, 'Prep vegetables', 'Peel and cut carrots into sticks. Wash and cut celery into sticks of similar length.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (302, 2, NULL, 'Serve', 'Scoop hummus into a small bowl in the center of a plate. Arrange the carrot and celery sticks around the hummus for dipping.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (303, 1, NULL, 'Fill celery', 'Wash and cut celery stalks into 4-inch pieces. Fill the groove of each piece with peanut butter.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (303, 2, NULL, 'Top and serve', 'Press dark chocolate chips into the peanut butter along the length of each celery stick. Arrange on a plate and serve.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (304, 1, NULL, 'Mix wet and dry', 'Preheat oven to 325°F. In a large bowl, combine rolled oats, honey, peanut butter, and a pinch of salt. Stir until everything is well coated. Fold in dark chocolate chips.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (304, 2, NULL, 'Press and bake', 'Press the mixture firmly and evenly into a parchment-lined 9x13 baking pan. Bake for 18-20 minutes until the edges turn golden.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (304, 3, NULL, 'Cool and cut', 'Let cool completely in the pan before cutting into 10 bars. Store in an airtight container.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (305, 1, NULL, 'Slice and arrange', 'Core and thinly slice the apples. Spread them out on a large plate in a single layer, nacho-style.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (305, 2, NULL, 'Add toppings', 'Drizzle peanut butter and honey over the apple slices. Sprinkle with granola and dark chocolate chips. Serve immediately.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (306, 1, NULL, 'Assemble the bowl', 'Spoon Greek yogurt into a bowl. Top with sliced banana, blueberries, and chia seeds.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (306, 2, NULL, 'Finish and serve', 'Drizzle with honey and serve immediately.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (307, 1, NULL, 'Spread and top', 'Spread peanut butter evenly over each rice cake (using crackers as the base). Top with sliced banana rounds.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (307, 2, NULL, 'Finish and serve', 'Drizzle with honey and serve immediately.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (308, 1, NULL, 'Toast the oats', 'In a dry skillet over medium heat, toast rolled oats for 3-4 minutes, stirring frequently, until golden and fragrant.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (308, 2, NULL, 'Season and toss', 'Drizzle melted butter over the toasted oats. Sprinkle with grated parmesan and paprika. Toss until evenly coated and serve warm.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (309, 1, NULL, 'Spread and top', 'Line a baking sheet with parchment paper. Spread Greek yogurt evenly into a thin layer, about 1/4 inch thick. Scatter blueberries, dark chocolate chips, and coconut flakes over the top, pressing gently.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (309, 2, NULL, 'Freeze and serve', 'Place in the freezer for at least 2 hours until completely frozen. Break into irregular bark pieces and serve immediately. Store leftover pieces in the freezer.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (310, 1, NULL, 'Melt the chocolate', 'Place dark chocolate chips in a heatproof bowl over a pot of simmering water. Stir gently until completely melted and smooth. Remove from heat and let cool slightly.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (310, 2, NULL, 'Whip the cream', 'In a chilled bowl, whip the heavy cream with vanilla extract until stiff peaks form.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (310, 3, NULL, 'Fold together', 'Gently fold one-third of the whipped cream into the melted chocolate to lighten it. Then fold in the remaining whipped cream in two additions, being careful not to deflate it.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (310, 4, NULL, 'Chill and serve', 'Divide the mousse among four serving glasses or ramekins. Refrigerate for at least 2 hours until set. Serve chilled.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (311, 1, NULL, 'Make the crust', 'Combine flour, butter, sugar, and a pinch of salt in a food processor. Pulse until crumbly. Press into a tart pan and bake at 375°F for 12-15 minutes until golden. Let cool completely.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (311, 2, NULL, 'Make the cream filling', 'Whisk together cream cheese and honey until smooth. Spread evenly over the cooled tart shell.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (311, 3, NULL, 'Top with fruit', 'Arrange sliced banana and fresh blueberries over the cream in a decorative pattern.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (311, 4, NULL, 'Serve', 'Refrigerate for 30 minutes to set, then slice and serve chilled.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (312, 1, NULL, 'Heat the cream', 'In a saucepan over medium heat, combine heavy cream, whole milk, honey, and vanilla extract. Heat until just simmering, stirring to dissolve the honey. Do not boil.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (312, 2, NULL, 'Set the mixture', 'Remove from heat. Pour the warm cream mixture into four ramekins or small glasses.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (313, 1, NULL, 'Blend the bananas', 'Add frozen banana pieces to a food processor or high-speed blender. Process for 3-4 minutes, scraping down the sides as needed, until the mixture is completely smooth and creamy like soft-serve ice cream.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (313, 2, NULL, 'Add mix-ins', 'Fold in dark chocolate chips and a splash of vanilla extract.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (313, 3, NULL, 'Serve', 'Serve immediately for soft-serve consistency, or freeze for 1 hour for a firmer scoop.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (314, 1, NULL, 'Prepare the filling', 'Preheat oven to 375°F. Toss blueberries with a tablespoon of sugar and a squeeze of lemon juice. Spread in a baking dish.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (314, 2, NULL, 'Make the crumble', 'In a bowl, combine rolled oats, flour, sugar, and cinnamon. Cut in cold butter with your fingers until the mixture resembles coarse crumbs.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (314, 3, NULL, 'Bake', 'Scatter the crumble topping evenly over the berries. Bake for 25-30 minutes until the topping is golden and the filling is bubbling.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (314, 4, NULL, 'Serve', 'Let cool for 10 minutes before serving. Delicious on its own or with a dollop of Greek yogurt.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (315, 1, NULL, 'Make the crust', 'Preheat oven to 350°F. Mix flour, butter, and 2 tablespoons of sugar until crumbly. Press firmly into the bottom of a greased 8x8 baking pan. Bake for 15 minutes until lightly golden.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (315, 2, NULL, 'Make the filling', 'While the crust bakes, whisk together eggs, remaining sugar, lemon juice, lemon zest, and a tablespoon of flour until smooth.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (315, 3, NULL, 'Bake', 'Pour the lemon filling over the hot crust. Return to the oven and bake for 18-20 minutes until the filling is just set and no longer jiggles.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (315, 4, NULL, 'Cool and serve', 'Let cool completely in the pan, then refrigerate for at least 1 hour. Cut into 9 squares and serve chilled.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (316, 1, NULL, 'Make the dough', 'Cream together softened butter and sugar until light and fluffy. Beat in the egg and vanilla extract. In a separate bowl, whisk flour, baking powder, and salt. Gradually mix the dry ingredients into the wet until just combined. Fold in dark chocolate chips.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (316, 2, NULL, 'Shape cookies', 'Drop rounded tablespoons of dough onto parchment-lined baking sheets, spacing them 2 inches apart.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (316, 3, NULL, 'Bake', 'Bake at 350°F for 10-12 minutes until the edges are golden but the centers still look slightly underdone. They will firm up as they cool.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (316, 4, NULL, 'Cool and serve', 'Let cool on the baking sheet for 5 minutes, then transfer to a wire rack. Serve warm or at room temperature.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (317, 1, NULL, 'Cook the rice', 'In a saucepan, combine cooked white rice, whole milk, sugar, and a pinch of salt. Bring to a gentle simmer over medium-low heat.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (317, 2, NULL, 'Simmer slowly', 'Cook for 25-30 minutes, stirring frequently, until the mixture thickens and becomes creamy. The rice should be very tender.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (317, 3, NULL, 'Finish and serve', 'Remove from heat and stir in vanilla extract and ground cinnamon. Serve warm or chilled, sprinkled with a dusting of cinnamon on top.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (318, 1, NULL, 'Make the cream filling', 'Beat together cream cheese, heavy cream, sugar, and vanilla extract until thick and fluffy.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (318, 2, NULL, 'Prepare the bread', 'Slice sourdough bread thinly. Briefly dip each slice in milk to soften slightly without making it soggy.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (318, 3, NULL, 'Layer the tiramisu', 'In a dish, layer the soaked bread slices and cream filling, repeating until all ingredients are used, finishing with a cream layer.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (318, 4, NULL, 'Chill and serve', 'Cover and refrigerate for at least 4 hours or overnight. Before serving, finely grate dark chocolate over the top.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (319, 1, NULL, 'Make the dough', 'In a saucepan, bring 1 cup water, butter, sugar, and a pinch of salt to a boil. Remove from heat and stir in flour vigorously until a smooth dough forms. Beat in the egg until fully incorporated.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (319, 2, NULL, 'Pipe and fry', 'Transfer the dough to a piping bag with a star tip. Pipe 4-inch strips into hot oil (375°F) and fry for 2-3 minutes per side until deep golden brown. Drain on paper towels.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (319, 3, NULL, 'Coat in cinnamon sugar', 'Mix granulated sugar and ground cinnamon together on a plate. Roll the warm churros in the cinnamon sugar until fully coated.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO recipe."RecipeStep" ("RecipeId", "StepNumber", "StepTypeId", "Summary", "Description", "Id", "CreatedDate", "CreatedByPersonId", "LastModifiedDate", "LastModifiedByPersonId", "IsDeleted", "DeletedAt", "DeletedByPersonId") VALUES (319, 4, NULL, 'Serve', 'Serve warm while still crispy. Optionally dip in melted chocolate.', 0, '2026-07-29 20:51:35-06', 1, NULL, NULL, false, NULL, NULL) ON CONFLICT DO NOTHING;
