-- Resync identity sequences to seeded max values
DO $$
DECLARE r RECORD; seqname TEXT; maxid BIGINT;
BEGIN
  FOR r IN
    SELECT table_schema, table_name FROM information_schema.columns
    WHERE column_name = 'Id' AND is_identity = 'YES'
      AND table_schema NOT IN ('pg_catalog','information_schema')
  LOOP
    seqname := pg_get_serial_sequence(format('%I.%I', r.table_schema, r.table_name), 'Id');
    IF seqname IS NOT NULL THEN
      EXECUTE format('SELECT COALESCE(MAX("Id"), 0) FROM %I.%I', r.table_schema, r.table_name) INTO maxid;
      IF maxid > 0 THEN PERFORM setval(seqname, maxid); END IF;
    END IF;
  END LOOP;
END $$;
COMMIT;

